"""`uv run minimeat-sim`: runs the ngspice checks and writes docs/sim/probe-frontend.md."""

from pathlib import Path

import numpy as np

from ..model.probes import PROBES
from . import frontend as F, ngspice

TEMPS_F = (32, 150, 225, 325, 500)
TOPOLOGIES = ("as_drawn", "bias_at_tip")


def main() -> None:
    if not ngspice.available():
        raise SystemExit("ngspice not found (brew install ngspice)")
    out = Path("docs/sim")
    out.mkdir(parents=True, exist_ok=True)
    md = ["# Probe front-end in ngspice", "",
          "Generated by `uv run minimeat-sim` (`src/minimeat/sim/frontend.py`). One channel as on the schematic: "
          "jack tip, R19 1k, the ADC node (C29 100 nF, 30 nA leakage), 47k bias to VREF_PROBE (3V3A through FB2, R18, C27, C28). "
          "The firmware converts the ratio assuming a bare 47k bias, as in `minimeat.model.probes`.", "",
          "## Reading error, settled (degF, reading minus truth, 30 nA input current)", "",
          "`as_drawn` is the schematic before the fix (bias on the ADC side of the 1k, so the 1k adds to the probe); "
          "`bias_at_tip` is ADR 0002's order and the schematic now.", "",
          "| Probe | Topology | " + " | ".join(f"{t} F" for t in TEMPS_F) + " |", "|---|---|" + "---|" * len(TEMPS_F)]
    for p in PROBES:
        for top in TOPOLOGIES:
            row = [f"{F.dc_error_f(top, p, t):+.2f}" for t in TEMPS_F]
            md.append(f"| {p.name} | {top} | " + " | ".join(row) + " |")
    md += ["", "## Settling after a probe is plugged in (bias_at_tip)", "",
           "Time for the reading to stay within 0.01 F of its final value, node starting at VREF (empty jack). "
           "The RC is the 47k bias against 100 nF.", "", "| Probe | 32 F | 225 F | 500 F |", "|---|---|---|---|"]
    for p in PROBES:
        row = [f"{F.settle_f('bias_at_tip', p, t)[0] * 1e3:.0f} ms" for t in (32, 225, 500)]
        md.append(f"| {p.name} | " + " | ".join(row) + " |")
    md += ["", "One 20 SPS conversion is 50 ms, so the first reading after a plug-in can still be settling. Firmware should "
           "drop the first conversion after a probe appears (to check against `drivers::ads122c04`).", "",
           "## Ripple on 3V3A", "",
           "Gain from 3V3A to REFP (the filtered VREF_PROBE) and to the ADC pin, 100 k probe (about 25 C), "
           "FB2 modelled as 0.2 ohm + 0.8 uH || 700 ohm [est].", "", "| Frequency | to REFP | to ADC pin |", "|---|---|---|"]
    f = np.array([60, 1e3, 1e4, 1e5, 256e3, 1.5e6])
    _, g = F.rail_ripple_db("bias_at_tip", f, 100e3)
    for fi, (a, b) in zip(f, g):
        md.append(f"| {fi:,.0f} Hz | {a:.1f} dB | {b:.1f} dB |")
    md += ["", f"A 20 mVpp 1.5 MHz buck ripple (assumed) is {20e3 * 10 ** (g[-1, 0] / 20):.0f} uV at REFP. "
           f"The ADS122C04's average input current of 5 nA (datasheet) at its 256 kHz modulator rate is a charge of "
           f"{5e-9 / 256e3 * 1e15:.0f} fC per cycle, {5e-9 / 256e3 / 100e-9 * 1e6:.1f} uV on the 100 nF node.", ""]
    (out / "probe-frontend.md").write_text("\n".join(md))
    print(out / "probe-frontend.md")


if __name__ == "__main__":
    main()
